<div class="customer-modal-backdrop" role="presentation"><section class="customer-modal employee-edit-modal" role="dialog" aria-modal="true" aria-labelledby="attendance-edit-title"><div class="customer-modal-header"><div><span class="modal-eyebrow">Attendance record</span><h2 id="attendance-edit-title">Edit Attendance</h2><span class="modal-code"><?= e($attendanceModalRecord['employee_code'] ?? '') ?></span></div><a class="customer-modal-close" href="index.php?page=admin&amp;section=employees-attendance" aria-label="Close">&times;</a></div><div class="customer-modal-body"><form method="post" action="index.php?page=admin&amp;section=employees-attendance"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="attendance_id" value="<?= (int)$attendanceModalRecord['id'] ?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Employee *</label><select class="form-select" name="employee_id" required><?php foreach($options as $option): ?><option value="<?= (int)$option['id'] ?>" <?= (int)$option['id']===(int)$attendanceModalRecord['employee_id']?'selected':'' ?>><?= e($option['name'].' ('.$option['employee_code'].')') ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Date *</label><input class="form-control" type="date" name="attendance_date" value="<?= e($attendanceModalRecord['attendance_date']) ?>" required></div><div class="col-md-6"><label class="form-label">Status *</label><select class="form-select" name="attendance_status" required><?php foreach(['present'=>'Present','absent'=>'Absent','leave'=>'Leave','half_day'=>'Half Day'] as $value=>$label): ?><option value="<?= $value ?>" <?= $attendanceModalRecord['attendance_status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Check In</label><input class="form-control" type="time" name="check_in" value="<?= e($attendanceModalRecord['check_in'] ?? '') ?>"></div><div class="col-md-3"><label class="form-label">Check Out</label><input class="form-control" type="time" name="check_out" value="<?= e($attendanceModalRecord['check_out'] ?? '') ?>"></div><div class="col-12"><label class="form-label">Notes</label><input class="form-control" name="attendance_notes" value="<?= e($attendanceModalRecord['notes'] ?? '') ?>"></div></div><div class="customer-modal-footer px-0 pb-0"><a class="btn btn-light" href="index.php?page=admin&amp;section=employees-attendance">Cancel</a><button class="btn btn-primary" type="submit">Update Attendance</button></div></form></div></section></div>
